# Try small SARIMA on log y, monthly seasonal
results=[]
ly=np.log(y)
for order in itertools.product(range(3), range(2), range(3)):
    p,d,q=order
    for seas in [(P,D,Q,12) for P in range(2) for D in range(2) for Q in range(2)]:
        try:
            mod=SARIMAX(ly, order=order, seasonal_order=seas, trend='c' if d==0 else 'n',
                        enforce_stationarity=False,enforce_invertibility=False)
            res=mod.fit(disp=False, maxiter=200)
            if res.mle_retvals.get('converged', True):
                fc=np.exp(res.get_forecast(1).predicted_mean.iloc[0])
                results.append((res.aicc, order, seas, fc, res.aic))
        except Exception as e:
            pass
len(results), sorted(results)[:10]

